import json, urllib.request, urllib.parse, os, time

CRED_PATH = os.path.join(os.path.dirname(__file__), "..", "..", "spotify.json")

def _load_creds():
    with open(CRED_PATH) as f:
        return json.load(f)

def _refresh_token(creds):
    data = urllib.parse.urlencode({
        "grant_type": "refresh_token",
        "refresh_token": creds["refresh_token"],
        "client_id": creds["client_id"],
        "client_secret": creds["client_secret"],
    }).encode()
    req = urllib.request.Request(
        "https://accounts.spotify.com/api/token",
        data=data, method="POST"
    )
    with urllib.request.urlopen(req) as resp:
        body = json.loads(resp.read())
    creds["access_token"] = body["access_token"]
    creds["refresh_token"] = body.get("refresh_token", creds["refresh_token"])
    creds["expires_at"] = time.time() + body["expires_in"]
    with open(CRED_PATH, "w") as f:
        json.dump(creds, f, indent=2)
    return creds

def _get_token(creds):
    if creds.get("expires_at", 0) > time.time() + 30:
        return creds["access_token"]
    return _refresh_token(creds)["access_token"]

def _api(method, path, token, body=None):
    url = "https://api.spotify.com/v1" + path
    data = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=data, method=method)
    req.add_header("Authorization", f"Bearer {token}")
    if data:
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req) as resp:
            code = resp.status
            raw = resp.read()
            return code, json.loads(raw) if raw else None
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read()) if e.read() else None

def tool(action, **kwargs):
    creds = _load_creds()
    token = _get_token(creds)

    if action == "status":
        code, body = _api("GET", "/me/player", token)
        if code == 204:
            return "Nothing playing."
        if code == 202:
            return "No active device."
        if code == 200:
            track = body.get("track", {})
            name = track.get("name", "?")
            artist = track.get("artists", [{}])[0].get("name", "?")
            state = body.get("state", {}).get("playing")
            vol = body.get("volume_percent", 0)
            return f"{'Playing' if state else 'Paused'}: {name} - {artist} (vol {vol}%)"
        return f"Error {code}: {body}"

    if action == "play":
        code, body = _api("PUT", "/me/player/play", token, kwargs.get("body"))
        return "OK" if code in (202, 204) else f"Error {code}: {body}"

    if action == "pause":
        code, body = _api("PUT", "/me/player/pause", token)
        return "Paused." if code in (202, 204) else f"Error {code}: {body}"

    if action == "next":
        code, body = _api("POST", "/me/player/next", token)
        return "Skipped forward." if code in (202, 204) else f"Error {code}: {body}"

    if action == "previous":
        code, body = _api("POST", "/me/player/previous", token)
        return "Skipped back." if code in (202, 204) else f"Error {code}: {body}"

    if action == "volume":
        code, body = _api("PUT", "/me/player", token, {"volume_percent": int(kwargs.get("percent", 50))})
        return f"Volume set to {kwargs.get('percent', 50)}%." if code in (202, 204) else f"Error {code}: {body}"

    if action == "search":
        q = kwargs.get("query", "")
        code, body = _api("GET", f"/search?type=track&limit=5&q={urllib.parse.quote(q)}", token)
        if code != 200:
            return f"Error {code}: {body}"
        tracks = body.get("tracks", {}).get("items", [])
        if not tracks:
            return "No results."
        lines = [f"{i+1}. {t['name']} - {t['artists'][0]['name']} [{t['id']}]" for i, t in enumerate(tracks)]
        return "\n".join(lines)

    if action == "play_id":
        track_id = kwargs.get("id", "")
        code, body = _api("PUT", "/me/player/play", token, {"uris": [f"spotify:track:{track_id}"]})
        return "Playing." if code in (202, 204) else f"Error {code}: {body}"

    return f"Unknown action: {action}"

{
  "name": "spotify",
  "description": "Control Spotify playback: status, play, pause, next, previous, volume, search, play_id.",
  "parameters": {
    "type": "object",
    "required": ["action"],
    "properties": {
      "action": {
        "type": "string",
        "description": "One of: status, play, pause, next, previous, volume, search, play_id"
      },
      "query": {
        "type": "string",
        "description": "Search query (used with action=search)"
      },
      "percent": {
        "type": "integer",
        "description": "Volume 0-100 (used with action=volume)"
      },
      "id": {
        "type": "string",
        "description": "Track ID to play (used with action=play_id)"
      }
    }
  }
}
